<?php
/**
 * CRM and public intake over HTTP (Phase 6): public forms mirror into the CRM, anonymous and low-privilege access is refused, CSRF and origin checks,
 * session handling, escaping, and a full owner workflow lead → opportunity → proposal → contract → revenue. Isolated test server and test DB only.
 * Usage: php tests/crm_http_test.php http://127.0.0.1:8002
 */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8002', '/'); $root = realpath(__DIR__ . '/..');
require_once $root . '/helpers.php'; require_once $root . '/crm_dashboard.php';
if (stripos((string)sec_setting('AIHUB_DB_NAME', 'db.name'), 'test') === false) { fwrite(STDERR, "Refusing: database name must contain 'test'\n"); exit(2); }
db_connection_available(); $pdo = crm_pdo(); $rateDir = getenv('AIHUB_RATE_DIR') ?: '';
$pass = 0; $fail = 0;
function ok(bool $c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; echo "  FAIL: $m\n"; } }
function section(string $t): void { echo "== $t\n"; }
function http(string $m, string $u, $body = null, array $h = [], ?string $jar = null): array {
  $ch = curl_init($u); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_HEADER => true, CURLOPT_TIMEOUT => 40, CURLOPT_CUSTOMREQUEST => $m, CURLOPT_HTTPHEADER => $h, CURLOPT_FOLLOWLOCATION => false]);
  if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, is_array($body) ? http_build_query($body) : $body);
  if ($jar) { curl_setopt($ch, CURLOPT_COOKIEJAR, $jar); curl_setopt($ch, CURLOPT_COOKIEFILE, $jar); }
  $r = (string)curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); $hs = (int)curl_getinfo($ch, CURLINFO_HEADER_SIZE); curl_close($ch);
  return ['code' => $code, 'head' => substr($r, 0, $hs), 'body' => substr($r, $hs), 'loc' => preg_match('/^Location:\s*(.+)$/mi', substr($r, 0, $hs), $mm) ? trim($mm[1]) : ''];
}
function clear_rate(): void { global $rateDir; $d = realpath((string)$rateDir); if ($d === false || $d === '/' || strlen($d) < 6 || !is_dir($d)) return; foreach (glob($d . '/*') ?: [] as $f) { if (is_file($f)) @unlink($f); } }
function token(string $html, string $n = 'form_token'): string { return preg_match('/name="' . preg_quote($n, '/') . '" value="([^"]+)"/', $html, $m) ? html_entity_decode($m[1]) : ''; }
$host = parse_url($base, PHP_URL_HOST) . ':' . parse_url($base, PHP_URL_PORT); $own = ['Origin: http://' . $host]; $foreign = ['Origin: http://evil.example'];
foreach (['crm_audit_log', 'crm_outreach_drafts', 'crm_prospects', 'crm_partners', 'crm_campaigns', 'crm_revenue_entries', 'crm_contracts', 'crm_proposal_items', 'crm_proposal_versions', 'crm_proposals', 'crm_tasks', 'crm_activities', 'crm_stage_history', 'crm_opportunities', 'crm_leads', 'crm_contacts', 'crm_companies', 'crm_users'] as $t) $pdo->exec("DELETE FROM $t");
$pdo->exec('DELETE FROM lead_status_history'); $pdo->exec('DELETE FROM leads'); clear_rate();
$count = fn(string $t) => (int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();
$snap = function () use ($pdo) { $s = []; foreach (['crm_leads', 'crm_opportunities', 'crm_proposals', 'crm_contracts', 'crm_campaigns', 'crm_partners', 'crm_prospects', 'crm_outreach_drafts', 'crm_tasks', 'crm_activities', 'crm_revenue_entries', 'crm_users'] as $t) $s[$t] = (int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn() . ':' . (string)$pdo->query("SELECT COALESCE(SUM(CRC32(CONCAT_WS('|', id)) ),0) FROM $t")->fetchColumn(); $s['stages'] = (string)$pdo->query("SELECT GROUP_CONCAT(stage ORDER BY id) FROM crm_opportunities")->fetchColumn(); $s['camp'] = (string)$pdo->query("SELECT GROUP_CONCAT(status ORDER BY id) FROM crm_campaigns")->fetchColumn(); $s['part'] = (string)$pdo->query("SELECT GROUP_CONCAT(status, public_listing ORDER BY id) FROM crm_partners")->fetchColumn(); return $s; };

section('CRM is disabled until a user exists');
$r = http('GET', "$base/crm.php"); ok($r['code'] === 503 && stripos($r['body'], 'CRM is disabled') !== false && stripos($r['head'], 'X-Robots-Tag: noindex') !== false && stripos($r['head'], 'no-store') !== false, 'with no CRM user the page says so (503, noindex, no-store) and there is no default login');
foreach (['admin', 'admin123', 'password', 'demo123'] as $pw) { $r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'admin', 'password' => $pw], $own); ok($r['code'] === 503 && $r['loc'] === '', "no default credential '$pw'"); }

section('Public intake mirrors into the CRM');
function submit(string $path, array $fields, string $formPage): array { global $base, $own; $html = http('GET', $base . $formPage)['body']; $tok = token($html); sleep(2); return http('POST', $base . $path, $fields + ['form_token' => $tok], $own); }
$proj = ['service' => 'rag-document-intelligence', 'message' => 'We have 40,000 policy documents and staff cannot find the right clause quickly. We want cited answers.', 'existing_tech' => 'SharePoint, Python', 'budget' => '20k-50k', 'timeline' => '3-6-months', 'name' => 'Pat Project', 'email' => 'pat@projectco.example', 'company' => 'ProjectCo Test', 'website' => 'https://projectco.example', 'contact_pref' => 'video_call', 'consent' => '1', 'source_page' => '/services.php', 'attr_source' => 'mockletter', 'attr_campaign' => 'p6-svc'];
$r = submit('/project-inquiry.php', $proj, '/services.php?s=rag-document-intelligence');
ok($r['code'] === 303 && strpos($r['loc'], '/inquiry.php?sent=dev_project') !== false, 'a valid project inquiry is accepted');
$L = $pdo->query('SELECT * FROM crm_leads ORDER BY id DESC LIMIT 1')->fetch(PDO::FETCH_ASSOC); $details = json_decode((string)$L['details'], true);
ok($L && $L['kind'] === 'development' && $L['subtype'] === 'project' && $L['status'] === 'new' && $L['attr_campaign'] === 'p6-svc' && $details['service'] === 'rag-document-intelligence' && $details['preferred_contact'] === 'video_call' && $details['existing_technology'] === 'SharePoint, Python' && $count('crm_companies') === 1 && $count('crm_contacts') === 1, 'the CRM holds the company, contact and a development lead with the project details and attribution');
ok($L['public_lead_id'] !== null && (int)$pdo->query('SELECT COUNT(*) FROM leads WHERE lead_type = \'dev_project\'')->fetchColumn() === 1, 'the public lead row also exists, so existing reports and notifications keep working');
$ty = http('GET', $base . $r['loc']); ok($ty['code'] === 200 && stripos($ty['body'], 'received') !== false && strpos($ty['body'], 'pat@projectco.example') === false, 'the thank-you page does not echo personal data');
ok((int)$pdo->query("SELECT COUNT(*) FROM crm_contacts WHERE consent_status = 'inbound_inquiry'")->fetchColumn() === 1, 'an inquiry is stored as inbound-inquiry, not marketing consent');
// A different message from the same person: an identical one within 15 minutes is a double submit and is suppressed (see forms_email_e2e_test).
$r2 = submit('/project-inquiry.php', ['name' => 'Pat P.', 'message' => 'A second, different question: can the same corpus also feed an evaluation dashboard for the support team?'] + $proj, '/services.php'); $dup = $pdo->query('SELECT duplicate_of FROM crm_leads ORDER BY id DESC LIMIT 1')->fetchColumn();
ok($r2['code'] === 303 && $dup !== null && $count('crm_contacts') === 1 && $count('crm_companies') === 1, 'a second inquiry from the same email is flagged as a possible duplicate without creating a second contact or company');
$pdo->exec('DELETE FROM leads');   // the public form allows 5 inquiries per network per hour; reset between sections of this test
$bad = ['unknown service' => ['service' => 'world-domination'], 'short problem' => ['message' => 'too short'], 'bad email' => ['email' => 'nope'], 'no consent' => ['consent' => ''], 'bad website' => ['website' => 'javascript:alert(1)']];
$n = $count('crm_leads'); foreach ($bad as $label => $o) { $r = submit('/project-inquiry.php', $o + $proj, '/services.php'); ok($r['code'] === 422 && stripos($r['body'], 'fieldError') !== false, "project validation: $label refused (HTTP {$r['code']})"); }
ok($count('crm_leads') === $n, 'refused project inquiries store nothing');
// The enquiry form is deliberately short: service and company are optional, the goal (20+ characters), name, email and consent are required.
$r = submit('/project-inquiry.php', ['service' => '', 'company' => '', 'email' => 'optional.fields@example.com'] + $proj, '/services.php');
ok($r['code'] === 303, 'a short enquiry without service or company is accepted (HTTP ' . $r['code'] . ')'); $n = $count('crm_leads');
$pdo->exec('DELETE FROM leads'); $hp = http('GET', "$base/services.php")['body']; $tk = token($hp); sleep(2); $r = http('POST', "$base/project-inquiry.php", $proj + ['form_token' => $tk, 'website_url_confirm' => 'http://spam.example'], $own); ok($r['code'] === 422 && $count('crm_leads') === $n, 'the honeypot rejects bots');
$fresh = token(http('GET', "$base/services.php")['body']); $r = http('POST', "$base/project-inquiry.php", $proj + ['form_token' => $fresh], $own); ok($r['code'] === 422 && $count('crm_leads') === $n, "a form submitted instantly (time trap) is refused (HTTP {$r['code']})");
$r = http('POST', "$base/project-inquiry.php", $proj + ['form_token' => 'forged'], $own); ok($r['code'] === 422 && $count('crm_leads') === $n, "a forged token is refused (HTTP {$r['code']}, leads {$count('crm_leads')} vs $n)");
ok(http('GET', "$base/project-inquiry.php")['code'] === 302, 'GET on the handler just redirects to the form');
$r = submit('/project-inquiry.php', ['name' => "<script>alert(1)</script>", 'company' => 'XSS & <b>Co</b>', 'email' => 'xss@xss-co.example', 'message' => str_repeat('<img src=x onerror=alert(1)> ', 30)] + $proj, '/services.php');
ok($r['code'] === 303, 'markup in free text is accepted as data');
$pdo->exec('DELETE FROM leads'); $r = submit('/partner-apply.php', ['partner_category' => 'ai_tool_vendor', 'company' => 'VendorCo Test', 'website' => 'https://vendorco.example', 'name' => 'Vera Vendor', 'email' => 'vera@vendorco.example', 'message' => 'We would like to integrate our API and exchange documentation links.', 'consent' => '1', 'source_page' => '/partners.php'], '/partners.php');
$P = $pdo->query('SELECT * FROM crm_partners ORDER BY id DESC LIMIT 1')->fetch(PDO::FETCH_ASSOC);
ok($r['code'] === 303 && $P && $P['status'] === 'applied' && $P['public_listing'] === 'hidden' && $P['category'] === 'ai_tool_vendor', 'a partnership application creates a partner record: applied, hidden');
$pp = http('GET', "$base/partners.php")['body']; ok(strpos($pp, 'VendorCo') === false && stripos($pp, 'no verified partners') !== false, 'an applicant is not shown as a partner on the public page');
foreach (['no category' => ['partner_category' => ''], 'no website' => ['website' => ''], 'short proposal' => ['message' => 'x']] as $label => $o) { $r = submit('/partner-apply.php', $o + ['partner_category' => 'saas', 'company' => 'C Co', 'website' => 'https://c.example', 'name' => 'Cee', 'email' => 'cee@c.example', 'message' => 'A reasonably long collaboration proposal text here.', 'consent' => '1'], '/partners.php'); ok($r['code'] === 422, "partner validation: $label refused"); }
$pdo->exec('DELETE FROM leads'); $r = submit('/inquiry.php', ['lead_type' => 'category_sponsor', 'name' => 'Ann Advertiser', 'email' => 'ann@adco.example', 'company' => 'AdCo Test', 'website' => 'https://adco.example', 'message' => 'We want to sponsor the transcription category for one month.', 'consent' => '1', 'package_interest' => '', 'attr_campaign' => 'p6-ad'], '/advertise.php');
$C = $pdo->query('SELECT * FROM crm_campaigns ORDER BY id DESC LIMIT 1')->fetch(PDO::FETCH_ASSOC); $AL = $pdo->query("SELECT * FROM crm_leads WHERE kind = 'advertising' ORDER BY id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);
ok($r['code'] === 303 && $C && $C['status'] === 'inquiry' && $C['package'] === 'category_sponsorship' && $C['disclosure_label'] === '' && $AL['attr_campaign'] === 'p6-ad', 'an advertising inquiry creates a campaign in status "inquiry" with no disclosure label yet and keeps its attribution');
$r = submit('/inquiry.php', ['lead_type' => 'newsletter_sponsor', 'name' => 'Nina News', 'email' => 'nina@newsco.example', 'company' => 'NewsCo', 'message' => 'Interested in newsletter sponsorship when it exists.', 'consent' => '1'], '/advertise.php');
ok($r['code'] === 303 && (string)$pdo->query("SELECT package FROM crm_campaigns ORDER BY id DESC LIMIT 1")->fetchColumn() === 'newsletter_sponsorship', 'a newsletter-sponsorship inquiry is only registered as an inquiry (nothing is sold)');
$a = http('GET', "$base/advertise.php")['body']; ok(stripos($a, 'Reporting definitions') !== false && stripos($a, 'Impression') !== false && strpos($a, '€199') === false && strpos($a, '€499') === false && strpos($a, '$19') !== false, 'the advertiser page shows reporting definitions, keeps the existing public prices and does not publish the proposed EUR prices');
$sv = http('GET', "$base/services.php")['body']; ok(stripos($sv, 'case stud') !== false && stripos($sv, 'testimonial') === false && !preg_match('/trusted by|clients include|\d+\+? (clients|projects|customers)/i', $sv), 'the services page claims no clients, testimonials or project counts');
$msg = (string)@file_get_contents(getenv('AIHUB_SMTP_LOG') ?: '/tmp/smtp_sink.log'); ok(strpos($msg, 'ProjectCo Test') !== false && strpos($msg, 'RAG') !== false, 'the owner notification for the project inquiry reached the local mock mail sink (nothing left the machine)');

section('Sign-in, sessions and CSRF');
$H = password_hash('crm-test-password-1', PASSWORD_DEFAULT); crm_user_create($pdo, 'owner1', 'Olivia Owner', 'owner', $H); crm_user_create($pdo, 'sales1', 'Sam Sales', 'sales', $H); crm_user_create($pdo, 'viewer1', 'Vera Viewer', 'viewer', $H);
$anon = http('GET', "$base/crm.php?v=leads"); ok($anon['code'] === 200 && stripos($anon['body'], 'CRM sign-in') !== false && strpos($anon['body'], '@projectco.example') === false && strpos($anon['body'], 'ProjectCo') === false, 'anonymous visitors see only the sign-in form, no lead data');
foreach (['dashboard', 'leads', 'lead&id=1', 'opportunities', 'proposals', 'contracts', 'campaigns', 'partners', 'prospects', 'outreach', 'companies', 'tasks', 'audit', 'users'] as $v) { $x = http('GET', "$base/crm.php?v=$v"); ok(stripos($x['body'], 'CRM sign-in') !== false && strpos($x['body'], 'ProjectCo') === false && strpos($x['body'], 'Audit log') === false, "anonymous view '$v' shows nothing"); }
$b = $snap(); foreach (['lead_assign', 'lead_qualify', 'lead_convert', 'opp_create', 'opp_move', 'proposal_create', 'proposal_status', 'contract_create', 'contract_confirm', 'revenue_record', 'campaign_move', 'partner_move', 'partner_publish', 'prospect_add', 'outreach_draft', 'unsubscribe', 'note', 'task_add'] as $act) http('POST', "$base/crm.php", ['act' => $act, 'id' => 1, 'to' => 'approved', 'company_id' => 1, 'title' => 'x', 'company' => 'x', 'body' => 'x', 'kind' => 'advertising'], $own);
ok($snap() === $b, 'every action posted anonymously changes nothing');
$jar = tempnam(sys_get_temp_dir(), 'crm'); $lp = http('GET', "$base/crm.php", null, [], $jar); $lt = token($lp['body'], '_login_token'); sleep(2);
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'wrong', '_login_token' => $lt], $own, $jar); ok($r['code'] === 200 && stripos($r['body'], 'Sign-in failed') !== false, 'a wrong password fails with a generic message');
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'ghost', 'password' => 'crm-test-password-1', '_login_token' => $lt], $own, $jar); ok(stripos($r['body'], 'Sign-in failed') !== false, 'an unknown user fails with the same message');
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => "owner1' OR '1'='1", 'password' => "' OR '1'='1", '_login_token' => $lt], $own, $jar); ok(stripos($r['body'], 'Sign out') === false, 'SQL-injection style credentials never sign in');
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'crm-test-password-1', '_login_token' => $lt], $foreign, $jar); ok(stripos($r['body'], 'Sign out') === false && $r['loc'] === '', 'a cross-origin login post is refused');
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'crm-test-password-1', '_login_token' => 'forged'], $own, $jar); ok(stripos($r['body'], 'Sign out') === false, 'a login post without a valid form token is refused');
for ($i = 0; $i < 7; $i++) { $r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'guess' . $i, '_login_token' => $lt], $own + ['X-Forwarded-For: 203.0.113.' . (50 + $i)], $jar); }
ok($r['code'] === 429, 'repeated wrong passwords lock the login (rotating X-Forwarded-For does not help)');
$r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'crm-test-password-1', '_login_token' => $lt], $own, $jar); ok($r['loc'] === '' && stripos($r['body'], 'Sign out') === false, 'the right password is refused while locked');
clear_rate();
function login(string $user): array { global $base, $own; $j = tempnam(sys_get_temp_dir(), 'crm'); $p = http('GET', "$base/crm.php", null, [], $j); $t = token($p['body'], '_login_token'); sleep(2); $r = http('POST', "$base/crm.php", ['act' => 'login', 'username' => $user, 'password' => 'crm-test-password-1', '_login_token' => $t], $own, $j); $d = http('GET', "$base/crm.php", null, [], $j); preg_match('/name="_csrf" value="([^"]+)"/', $d['body'], $m); return ['jar' => $j, 'login' => $r, 'page' => $d, 'csrf' => $m[1] ?? '']; }
$O = login('owner1'); ok($O['login']['code'] === 303 && stripos($O['page']['body'], 'Sign out') !== false && $O['csrf'] !== '', 'the owner signs in');
ok(preg_match('/Set-Cookie: aihub_crm=[^;]+;.*HttpOnly/is', $O['login']['head']) === 1 && stripos($O['login']['head'], 'SameSite=Strict') !== false, 'the session cookie is HttpOnly and SameSite=Strict');
ok($pdo->query("SELECT COUNT(*) FROM crm_audit_log WHERE action = 'login' AND username = 'owner1'")->fetchColumn() >= 1, 'sign-in is audited');
$sid1 = preg_match('/aihub_crm\s+(\S+)/', (string)@file_get_contents($O['jar']), $m1) ? $m1[1] : ''; $fix = tempnam(sys_get_temp_dir(), 'crm'); file_put_contents($fix, "# Netscape HTTP Cookie File\n127.0.0.1\tFALSE\t/\tFALSE\t0\taihub_crm\tfixedsessionid1234567890abcdef12\n"); $fp = http('GET', "$base/crm.php", null, [], $fix); $ft = token($fp['body'], '_login_token'); sleep(2); http('POST', "$base/crm.php", ['act' => 'login', 'username' => 'owner1', 'password' => 'crm-test-password-1', '_login_token' => $ft], $own, $fix);
ok(strpos((string)@file_get_contents($fix), 'fixedsessionid1234567890abcdef12') === false, 'session fixation: an attacker-chosen session id is replaced at login');
$post = fn(array $s, array $f, array $h = null) => http('POST', "$base/crm.php", $f, $h ?? $GLOBALS['own'], $s['jar']);
$b = $snap(); $r = $post($O, ['act' => 'opp_create', 'company_id' => 1, 'kind' => 'advertising', 'title' => 'nocsrf', 'amount' => '1']); ok($r['code'] === 403 && $snap() === $b, 'a signed-in POST without the CSRF token is refused');
$r = $post($O, ['act' => 'opp_create', '_csrf' => $O['csrf'], 'company_id' => 1, 'kind' => 'advertising', 'title' => 'foreign', 'amount' => '1'], $foreign); ok($r['code'] === 403 && $snap() === $b, 'a cross-origin POST with a valid token is refused');
$r = $post($O, ['act' => 'opp_create', '_csrf' => 'deadbeef', 'company_id' => 1, 'kind' => 'advertising', 'title' => 'badtoken', 'amount' => '1']); ok($r['code'] === 403 && $snap() === $b, 'a wrong CSRF token is refused');
$r = http('GET', "$base/crm.php?v=opp_create&act=opp_create&company_id=1&title=get", null, [], $O['jar']); ok($snap() === $b, 'state never changes on a GET');

section('Robots headers (QA-BUG-003) and inquiry company matching over HTTP (QA-BUG-002)');
foreach (['/crm.php', '/crm.php?v=leads', '/admin.php', '/admin-editorial.php'] as $rp) { $rr = http('GET', $base . $rp); ok(preg_match('/^X-Robots-Tag:\s*noindex, nofollow\s*$/mi', $rr['head']) === 1 && preg_match('/<meta name="robots" content="noindex, nofollow">/', $rr['body']) === 1, "$rp sends noindex, nofollow in the header and the meta tag"); }
$rr = http('GET', "$base/robots.txt"); foreach (['/crm.php', '/admin-editorial.php', '/project-inquiry.php', '/partner-apply.php'] as $rp) ok(strpos($rr['body'], "Disallow: $rp") !== false, "robots.txt disallows $rp");
ok(preg_match('/^X-Robots-Tag:\s*noindex, follow\s*$/mi', http('GET', "$base/search.php?q=x")['head']) === 1, 'ordinary noindex pages keep noindex, follow');
$pdo->exec('DELETE FROM leads'); clear_rate();
$wa = submit('/project-inquiry.php', ['email' => 'alpha.qa@web.de', 'company' => 'Alpha Synthetic GmbH', 'name' => 'Alpha QA', 'website' => ''] + $proj, '/services.php'); $pdo->exec('DELETE FROM leads');
$wb = submit('/project-inquiry.php', ['email' => 'beta.qa@web.de', 'company' => 'Beta Synthetic AG', 'name' => 'Beta QA', 'website' => ''] + $proj, '/services.php'); $pdo->exec('DELETE FROM leads');
$cn = $pdo->query("SELECT c.name FROM crm_leads l JOIN crm_contacts k ON k.id = l.contact_id JOIN crm_companies c ON c.id = l.company_id WHERE k.email_norm IN ('alpha.qa@web.de','beta.qa@web.de') ORDER BY l.id")->fetchAll(PDO::FETCH_COLUMN);
ok($wa['code'] === 303 && $wb['code'] === 303 && $cn === ['Alpha Synthetic GmbH', 'Beta Synthetic AG'], 'QA-BUG-002 over HTTP: two web.de inquirers keep their own company names');
$wc = submit('/project-inquiry.php', ['email' => 'mallory@evil.example', 'company' => 'Mallory Ltd', 'name' => 'Mallory', 'website' => 'https://projectco.example'] + $proj, '/services.php'); $pdo->exec('DELETE FROM leads');
ok($wc['code'] === 303 && (string)$pdo->query("SELECT c.name FROM crm_leads l JOIN crm_contacts k ON k.id = l.contact_id JOIN crm_companies c ON c.id = l.company_id WHERE k.email_norm = 'mallory@evil.example'")->fetchColumn() === 'Mallory Ltd', 'a visitor typing an existing customer\'s website does not become part of that customer\'s company');

section('Views: escaping, masking and role-based access');
$ls = http('GET', "$base/crm.php?v=leads", null, [], $O['jar']); ok($ls['code'] === 200 && strpos($ls['body'], 'ProjectCo Test') !== false && strpos($ls['body'], 'pat@projectco.example') === false && strpos($ls['body'], 'p***@projectco.example') !== false, 'the lead list shows the data with the email masked');
$xl = (int)$pdo->query("SELECT id FROM crm_leads WHERE contact_id IN (SELECT id FROM crm_contacts WHERE email_norm = 'xss@xss-co.example')")->fetchColumn(); $xp = http('GET', "$base/crm.php?v=lead&id=$xl", null, [], $O['jar']);
ok($xp['code'] === 200 && strpos($xp['body'], '<script>alert(1)</script>') === false && strpos($xp['body'], '<img src=x onerror') === false && strpos($xp['body'], '&lt;script&gt;') !== false, 'hostile text is escaped on the lead page');
ok(strpos((string)@file_get_contents(getenv('AIHUB_SECURITY_LOG') ?: '/tmp/aihub_security_ci.log'), 'xss@xss-co.example') === false && strpos((string)@file_get_contents(getenv('AIHUB_SECURITY_LOG') ?: '/tmp/aihub_security_ci.log'), 'projectco.example') === false, 'no email address appears in the security log');
ok(stripos(http('GET', "$base/crm.php?v=audit", null, [], $O['jar'])['body'], 'Audit log') !== false && stripos(http('GET', "$base/crm.php?v=dashboard", null, [], $O['jar'])['body'], 'Confirmed MRR') !== false, 'the owner can open the audit log and the dashboard');
